// Copies the compiled creation bytecode of the CONNEX contracts into the site for /deploy
// and for scripts/verify-deployment.mjs. Run after `forge build` in contracts/:
//   node scripts/onchain-bytecode.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";

const NAMES = ["ConnexTreasury", "ConnexLauncher", "ConnexBuyback"];
let out = `// Generated by scripts/onchain-bytecode.mjs from contracts/src (solc 0.8.26, optimizer 200 runs,
// via-ir, evm cancun, no metadata hash). Do not edit.\n`;
for (const name of NAMES) {
  const artifact = JSON.parse(readFileSync(new URL(`../contracts/out/${name}.sol/${name}.json`, import.meta.url)));
  const bytecode = artifact.bytecode.object;
  const runtime = artifact.deployedBytecode.object;
  const sha = createHash("sha256").update(bytecode).digest("hex");
  out += `\n// ${name}: ${bytecode.length / 2 - 1} bytes, sha256 ${sha}\n`;
  out += `export const ${name.toUpperCase()}_BYTECODE = "${bytecode}";\n`;
  out += `export const ${name.toUpperCase()}_RUNTIME = "${runtime}";\n`;
  console.log(`${name}: ${bytecode.length / 2 - 1} bytes, sha256 ${sha}`);
}
writeFileSync(new URL("../src/lib/onchain/bytecode.ts", import.meta.url), out);
